import{_ as o,a,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · 单元 2 语法总结 · 动词、宾语与补足语至时间、原因与让步从句","description":"L25–L48 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 2 语法总结 · 动词、宾语与补足语至时间、原因与让步从句","description":"L25–L48 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-02/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 2 语法总结","summary":"L25–L48 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式","link":"/life/english/new-concept/book-2/unit-02/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 2 单词与短语","link":"/life/english/new-concept/book-2/unit-02/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 2 语法总结 · 现在完成时与过去时间至情态动词的意义与形式","link":"/life/english/new-concept/book-2/unit-02/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 2 单词与短语","link":"/life/english/new-concept/book-2/unit-02/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/grammar-part-03.md","filePath":"life/english/new-concept/book-2/unit-02/grammar-part-03.md"}'),r={name:"life/english/new-concept/book-2/unit-02/grammar-part-03.md"};function i(s,e,l,p,c,h){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-2-语法总结-·-动词、宾语与补足语至时间、原因与让步从句" tabindex="-1">第二册：实践与进步 · 单元 2 语法总结 · 动词、宾语与补足语至时间、原因与让步从句 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-语法总结-·-动词、宾语与补足语至时间、原因与让步从句" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 语法总结 · 动词、宾语与补足语至时间、原因与让步从句&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-02/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><h2 id="动词、宾语与补足语" tabindex="-1">动词、宾语与补足语 <a class="header-anchor" href="#动词、宾语与补足语" aria-label="Permalink to &quot;动词、宾语与补足语 {#动词、宾语与补足语}&quot;">​</a></h2><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：watch somebody move 强调看到整体动作，watch somebody moving 强调正在进行的片段；两种形式都不加 to。</p><p><strong>L42 原创例句：</strong> We watched the bird move towards the musician&#39;s hand.</p><p>我们看着那只鸟朝乐手的手移动。</p><p><strong>易错：</strong> watched the bird to move 不合此感官动词结构；主动式通常省略 to。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-042">Lesson 42</a></p><h2 id="真实条件句" tabindex="-1">真实条件句 <a class="header-anchor" href="#真实条件句" aria-label="Permalink to &quot;真实条件句 {#真实条件句}&quot;">​</a></h2><p>谈论有可能发生的未来条件时，常用 if 加一般现在时，主句用 will、can 或祈使句。if 从句说明条件，不是独立预测，因此通常不用 will 表单纯将来；表达意愿等特殊含义时则另当别论。unless 表示“除非”，常相当于 if ... not，但不适用于所有逻辑关系。条件句并不保证条件会发生，写作时要把假设与已知事实分开。本课应用：If we keep to the path ... 表仍可实现的条件；主句 can reach 表可行结果而不是保证。条件本身不需要 will。</p><p><strong>L44 原创例句：</strong> If we keep to the path, we can reach the village before dark.</p><p>如果沿着小路走，我们能在天黑前到村庄。</p><p><strong>易错：</strong> If we will keep ... 在普通真实条件句中多余；用 If we keep。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-044">Lesson 44</a></p><h2 id="数量表达与范围" tabindex="-1">数量表达与范围 <a class="header-anchor" href="#数量表达与范围" aria-label="Permalink to &quot;数量表达与范围 {#数量表达与范围}&quot;">​</a></h2><p>many、few 修饰可数复数，much、little 修饰不可数名词；a few 和 a little 强调有一些，few 和 little 往往强调不足。all、both、each、every 的范围不同，谓语单复数要看实际主语而不是最近的名词。数量比较中的 more、less、fewer 也需结合可数性。表述统计或费用时要给出单位和参照范围，避免只有数字却没有明确对象。本课应用：less comfortable 比较舒适程度，more money 比较不可数的费用。fewer 只适合可数复数，如 fewer seats，不能说 fewer money。</p><p><strong>L46 原创例句：</strong> The overnight train cost more but offered fewer comfortable seats.</p><p>夜间列车更贵，却提供了更少的舒适座位。</p><p><strong>易错：</strong> fewer comfort 不对，comfort 通常不可数；可说 less comfort 或 fewer comfortable seats。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-046">Lesson 46</a></p><h2 id="时间、原因与让步从句" tabindex="-1">时间、原因与让步从句 <a class="header-anchor" href="#时间、原因与让步从句" aria-label="Permalink to &quot;时间、原因与让步从句 {#时间、原因与让步从句}&quot;">​</a></h2><p>状语从句为主句提供时间、原因、条件或让步背景。连接词不仅连接形式，也表达逻辑：because 给原因，although 表示让步，while 可以表示同时或对照，until 标记持续的终点。英语通常不把 although 与 but、because 与 so 成对放在同一个复合句中。从句置前时一般用逗号隔开；选连接词前先判断两件事之间的实际关系。本课应用：as soon as 表一个动作发生后紧接另一个；while 强调同时过程，不能随意替换，否则会把先后变成同时。</p><p><strong>L48 原创例句：</strong> As soon as the dentist removed the mirror, I asked a question.</p><p>牙医一拿开镜子，我就问了一个问题。</p><p><strong>易错：</strong> while he removed the mirror 不一定等于拿开之后；表达紧接应使用 as soon as。</p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-048">Lesson 48</a></p>',27)])])}const f=o(r,[["render",i]]);export{m as __pageData,f as default};
